    """Smallest index at which x can be inserted to keep a sorted (bisect_left)."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def solve(n, b):
