def solve(grid):
    """Count the number of islands in a 2D binary grid.
    An island is a group of horizontally or vertically adjacent cells with value 1.
    Empty grid returns 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                # BFS/DFS stack
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
    return count

def solve(s):
    # Sliding window to find longest substring without repeating characters.
    # Use a dictionary to store the last index of each character.
    last_idx = {}
    max_len = 0
    start = 0  # left bound of current window
    for i, ch in enumerate(s):
        if ch in last_idx and last_idx[ch] >= start:
            # character repeated inside current window, move start right after previous occurrence
            start = last_idx[ch] + 1
        last_idx[ch] = i
        # current window length is i - start + 1
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

