    """Greedy word wrap.
    Packs words into lines not exceeding *width* characters, using a single space between words.
    If a single word's length exceeds *width*, it occupies a line on its own.
    """
    # Edge case: non‑positive width – each word must be on its own line.
    if width <= 0:
        return list(words)
    if not words:
        return []
    lines = []
    cur_words = []
    cur_len = 0  # length of current line without spaces
    for w in words:
        if not cur_words:
            cur_words.append(w)
            cur_len = len(w)
        else:
            prospective = cur_len + 1 + len(w)
            if prospective <= width:
                cur_words.append(w)
                cur_len = prospective
            else:
                lines.append(' '.join(cur_words))
                cur_words = [w]
                cur_len = len(w)
    if cur_words:
