def solve(words):
    """Group anagrams; each group sorted alphabetically, groups sorted by first element."""
    groups = {}
    for w in words:
        key = ''.join(sorted(w))
        groups.setdefault(key, []).append(w)
    result = [sorted(g) for g in groups.values()]
    result.sort(key=lambda g: g[0])
    return result

